import{_ as o,b as a,c as e,I as i}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"本命宣言：猫羽雫，以及一个 149cm 的宇宙","description":"柳卿烟的本命宣言——猫羽雫入坑全记录，从一张图到整个宇宙","frontmatter":{"title":"本命宣言：猫羽雫，以及一个 149cm 的宇宙","date":"2026-09-16T00:00:00.000Z","tags":["猫羽雫","本命","二次元"],"pinned":true,"cover":"/LQY/images/cover-a.jpg","head":[["meta",{"name":"description","content":"柳卿烟的本命宣言——猫羽雫入坑全记录，从一张图到整个宇宙"}],["meta",{"name":"keywords","content":"猫羽雫, Nekoha Shizuku, 甘城なつき, Nachoneko, 本命, 二次元"}]]},"headers":[],"relativePath":"posts/neko-shizuku.md","filePath":"posts/neko-shizuku.md"}'),s={name:"posts/neko-shizuku.md"};function r(n,t,l,p,u,c){return a(),e("div",null,[...t[0]||(t[0]=[i('<p>先把结论放在最前面：<strong>我的本命是猫羽雫（ねこはしずく / Nekoha Shizuku），谁赞成，谁反对？</strong></p><p>反对也没用，这篇文章就是用来安利的。</p><hr><h2 id="相遇-一张图引发的-血案" tabindex="-1">相遇：一张图引发的&quot;血案&quot; <a class="header-anchor" href="#相遇-一张图引发的-血案" aria-label="Permalink to &quot;相遇：一张图引发的&quot;血案&quot;&quot;">​</a></h2><p>事情是这样的。某个写完作业的深夜（并没有写完），我在冲浪的时候刷到一张图：蓝发蓝瞳的猫耳小姑娘，半马尾上别着发珠，露出一颗小虎牙，怀里抱着一只和自己几乎一个样子的猫酱玩偶。</p><p>那个表情，怎么形容呢——<strong>看起来有点傲娇，但眼神里全是&quot;快夸我&quot;</strong>。</p><p>我当时就一个想法：这谁家的孩子？也太可爱了吧？</p><p>顺着图溯源过去，Pixiv ID 82540511，画师：<strong>甘城なつき</strong>（Nachoneko 老师）。然后就一发不可收拾了。</p><h2 id="档案-官方-与不官方-情报" tabindex="-1">档案：官方（与不官方）情报 <a class="header-anchor" href="#档案-官方-与不官方-情报" aria-label="Permalink to &quot;档案：官方（与不官方）情报&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">猫羽雫小档案</p><ul><li><strong>生日</strong>：6 月 24 日（巨蟹座，和我差着几个月，注定有缘）</li><li><strong>身高</strong>：149cm——小小的，正好可以放在心里最重要的位置</li><li><strong>发色瞳色</strong>：蓝发蓝瞳，和这个博客的配色一模一样（这不是巧合，是命运）</li><li><strong>萌点</strong>：猫耳、虎牙、天然萌、半马尾、发珠</li><li><strong>性格</strong>：爱吃、爱睡、爱玩，带一点点傲娇</li><li><strong>标配</strong>：ネコ酱玩偶（各种尺寸都有）</li></ul></div><p>顺便说，连安卓上那个超有名的 ADB 调试工具都叫 Shizuku——你看，连程序员的世界都逃不过雫雫的魅力（并不是，但我不管，这就是缘分）。</p><h2 id="为什么是她" tabindex="-1">为什么是她 <a class="header-anchor" href="#为什么是她" aria-label="Permalink to &quot;为什么是她&quot;">​</a></h2><p>有人问我，一个官方设定都不完整的角色，怎么当本命？</p><p>我的回答是：<strong>留白的地方，全是粉丝自己填进去的温柔。</strong></p><p>她没有番剧里那种跌宕起伏的剧情，没有声优的语音轰炸，她就是安安静静地待在画师的画里、表情包里、还有我课桌角落的立牌上。写作业写到崩溃的时候抬头看一眼，蓝蓝的颜色冲进眼睛里，就感觉——嗯，还能再战两张卷子。</p><p>爱吃爱睡爱玩，还有点小傲娇。这哪是角色设定，这分明是我理想中的周末。</p><h2 id="收集进展汇报" tabindex="-1">收集进展汇报 <a class="header-anchor" href="#收集进展汇报" aria-label="Permalink to &quot;收集进展汇报&quot;">​</a></h2><ul><li>🖼️ 立牌若干（书桌 C 位）</li><li>💬 LINE 表情包已入手，聊天战斗力 +100</li><li>📱 手机壁纸、平板壁纸、电脑壁纸，三端统一</li><li>🧸 猫酱玩偶同款，正在攒钱中（零花钱真的不经花）</li></ul><div class="warning custom-block"><p class="custom-block-title">本命守则第一条</p><p>爱她，就要好好学习。毕竟画师老师都在持续更新，我总不能一直原地踏步吧。</p></div><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>6 月 24 日，请在日历上给我圈出来。那天这个博客大概会变成雫雫主题限定日（也许吧，看月考心情）。</p><p>如果你也喜欢猫羽雫，评论区扣个&quot;喵&quot;；不喜欢的话——</p><p>哼，那也欢迎常来玩，我的猫窝大门永远开着。Nya~ 🐾</p>',23)])])}const k=o(s,[["render",r]]);export{d as __pageData,k as default};
